function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // clock for time, 288 can be 288 minutes or 4.8 hours
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  // hour hand
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2);
  ctx.lineTo(W / 2 + 30 * Math.sin(t), H / 2 - 30 * Math.cos(t));
  ctx.stroke();
  // minute hand
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2);
  ctx.lineTo(W / 2 + 40 * Math.sin(10 * t), H / 2 - 40 * Math.cos(10 * t));
  ctx.stroke();
  // numbers
  for (let i = 1; i <= 12; i++) {
    ctx.font = '20px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = 'black';
    ctx.fillText(i, W / 2 + 45 * Math.sin(2 * Math.PI * i / 12), H / 2 - 45 * Math.cos(2 * Math.PI * i / 12));
  }
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('288', W / 2, H / 2 + 60);
  ctx.restore();
}
